get
            {
                if (!this.Parent.IsExternal)
                    return ProjectIcon;

                try
                {
                    // מוציא את האייקון המותאם למערכת מהקובץ
                    Icon sysIcon = Icon.ExtractAssociatedIcon(Versions?.FirstOrDefault().FullPath);
                    return Imaging.CreateBitmapSourceFromHIcon(
                        sysIcon.Handle,
                        Int32Rect.Empty,
                        BitmapSizeOptions.FromWidthAndHeight(16, 16)
                    );
                }
                catch
                {
                    // במקרה של שגיאה – נחזיר אייקון ברירת מחדל או null
                    return null;
                }
            }

