await Application.Current.Dispatcher.InvokeAsync(() =>
                {
                    // Projects
                    foreach (var p in dbContext.Projects.Local.OrderByDescending(p => p.Number))
                        Projects.Add(p);

                    // Places: only InUse, sorted
                    foreach (var p in dbContext.Places.Local.Where(p => p.InUse == true).OrderBy(p => p.Title))
                        Places.Add(p);

                    // Companies: sorted
                    foreach (var c in dbContext.Companies.Local.OrderBy(c => c.Title))
                        Companies.Add(c);

                    // JobTypes: sorted
                    foreach (var j in dbContext.JobTypes.Local.OrderBy(j => j.Title))
                        JobTypes.Add(j);

                    // ProjectStatuses: sorted
                    foreach (var s in dbContext.ProjectStatuses.Local.OrderBy(s => s.Title))
                        ProjectStatuses.Add(s);

                    // Users: active with email, sorted
                    foreach (var u in dbContext.Siusers.Local.Where(u => u.IsActive && !string.IsNullOrWhiteSpace(u.Email)).OrderBy(u => u.Name))
                        Users.Add(u);

                    // Re-apply default filter selections
                    SelectedPlaceFilter = Places[0];
                    SelectedCompanyFilter = Companies[0];
                    SelectedJobTypeFilter = JobTypes[0];
                    SelectedStatusFilter = ProjectStatuses[0];
                    SelectedUserFilter = Users[0];

                    ProjectsView.Refresh();

                    // Auto-select initial project if specified
                    if (InitialProjectId.HasValue)
                    {
                        var target = Projects.FirstOrDefault(p => p.Id == InitialProjectId.Value);
                        if (target != null)
                        {
                            SelectedProject = target;
                            ShowProjectSelector = false;
                        }
                    }
                });

