Application.Current.Dispatcher.Invoke(() =>
            {
                bool isFile = Path.HasExtension(e.FullPath);
                bool isDirectory = !isFile;

                if (isDirectory)
                {
                    RefreshTreePreserveState();
                }
                else
                {
                    // הנתיב ששינה
                    var changedPath = Path.GetFullPath(e.FullPath)
                                          .TrimEnd(Path.DirectorySeparatorChar);
                    var selectedPath = "";
                    try
                    {
                        // אם הקובץ לא קיים יותר – נרענן את העץ
                        // הנתיב של ה־SelectedNode (עם סלאש בסוף להשוואת תת־תיקיות)
                        selectedPath = Path.GetFullPath(SelectedNode.FullPath)
                                              .TrimEnd(Path.DirectorySeparatorChar)
                                          + Path.DirectorySeparatorChar;
                    }
                    catch (Exception ex)
                    {
                        // אם יש שגיאה בגישה לקובץ, אפשר להדפיס לוג או לטפל אחרת
                        Console.WriteLine($"Error accessing file: {ex.Message}");
                        return;
                    }



                    // רק אם הקובץ בתוך ה־SelectedNode
                    if (changedPath.StartsWith(selectedPath, StringComparison.OrdinalIgnoreCase))
                    {
                        LoadFilesForSelectedNode();
                    }
                }

            });

