cm.Opened += async (_, __) =>
                {
                    createAcc.Header = "...בודק ACC";
                    createAcc.Visibility = Visibility.Visible;
                    createAcc.IsEnabled = false;
                    openAcc.Visibility = Visibility.Collapsed;
                    try
                    {
                        var exists = await ProbeAccFolderExistsAsync().ConfigureAwait(true);
                        if (exists.HasValue && exists.Value)
                        {
                            createAcc.Visibility = Visibility.Collapsed;
                            openAcc.Visibility = Visibility.Visible;
                        }
                        else if (exists.HasValue && !exists.Value)
                        {
                            createAcc.Header = "צור תיקייה ב-ACC";
                            createAcc.IsEnabled = true;
                            createAcc.Visibility = Visibility.Visible;
                            openAcc.Visibility = Visibility.Collapsed;
                        }
                        else
                        {
                            // Could not determine (no mapping / error) — hide both.
                            createAcc.Visibility = Visibility.Collapsed;
                            openAcc.Visibility = Visibility.Collapsed;
                        }
                    }
                    catch
                    {
                        createAcc.Visibility = Visibility.Collapsed;
                        openAcc.Visibility = Visibility.Collapsed;
                    }
                };

