_ = app.Dispatcher.InvokeAsync(async () =>
                    {
                        if (att.SelectedAlternativeId != finalId)
                        {
                            AppLogger.Info($"[AltSelect] FAILSAFE — WPF reset detected! Re-applying: {finalId} (was {att.SelectedAlternativeId})");
                            att.PropertyChanged -= OnAttachmentTagChanged;
                            att.SelectedAlternativeId = finalId;
                            att.PropertyChanged += OnAttachmentTagChanged;

                            // Persist corrected value to DB so file sync uses the right alternative
                            var tagSvc = new AttachmentTaggingService();
                            await tagSvc.SetAttachmentAlternativeAsync(attId, finalId);
                            AppLogger.Info($"[AltSelect] FAILSAFE — Persisted to DB: AttId={attId}, AltId={finalId}");
                        }
                    }, System.Windows.Threading.DispatcherPriority.Loaded);

