snippetModel.unrestricted:
await Application.Current.Dispatcher.InvokeAsync(() =>
                {
                    var displayable = email.AllDisplayableAttachments;

                    foreach (var dbAtt in dbAttachments)
                    {
                        var hasAccId = !string.IsNullOrEmpty(dbAtt.AccItemId);

                        // Try to match an existing in-memory attachment by filename
                        var inMemory = displayable.FirstOrDefault(a =>
                            string.Equals(a.FileName, dbAtt.OriginalFileName, StringComparison.OrdinalIgnoreCase)
                            || string.Equals(
                                MessageKeyGenerator.SanitizeFileName(a.FileName),
                                dbAtt.SavedFileName,
                                StringComparison.OrdinalIgnoreCase));

                        if (inMemory != null)
                        {
                            // Mark existing attachment with ACC status and origin
                            inMemory.IsInAcc = hasAccId;
                            inMemory.AccItemId = dbAtt.AccItemId;
                            inMemory.IsExternalDownload = dbAtt.IsExternalDownload;
                            inMemory.IsEmailFiledToProject = email.IsFiledInGmail;
                            // Populate tag info from DB
                            ApplyTagInfoFromDb(inMemory, dbAtt, inboxMessage.ProjectId);
                            AppLogger.Info($"[TagDiag] SyncAcc — matched '{inMemory.FileName}': InboxAttachmentId={inMemory.InboxAttachmentId}, " +
                                $"IsEmailFiledToProject={inMemory.IsEmailFiledToProject}, ShowTagSelector={inMemory.ShowTagSelector}");
                        }
                        else if (hasAccId && dbAtt.IsExternalDownload)
                        {
                            // External download not yet in the display list — add it
                            var newEntry = new EmailAttachment
                            {
                                FileName = dbAtt.OriginalFileName ?? dbAtt.SavedFileName ?? "unknown",
                                MimeType = "application/octet-stream",
                                IsAccOnly = true,
                                IsInAcc = true,
                                IsExternalDownload = true,
                                IsEmailFiledToProject = email.IsFiledInGmail,
                                AccItemId = dbAtt.AccItemId
                            };
                            ApplyTagInfoFromDb(newEntry, dbAtt, inboxMessage.ProjectId);
                            newExternalEntries.Add(newEntry);
                        }
                    }

                    // Add any new external entries to the display list
                    foreach (var entry in newExternalEntries)
                    {
                        email.AddExternalDownload(entry);
                    }

                    // Force refresh the list so bindings pick up IsInAcc changes
                    email.RefreshAttachmentDisplay();
                });

