                    email.AssignedProjectId = project.Id;
                    email.ContextState = EmailContextState.Filed;
                    // Clear thread context since it's now directly assigned
                    email.ThreadAssignedProjectId = null;
                    email.ThreadAssignedProjectName = string.Empty;

                    // STEP 3: Update peer emails in the same thread
                    // Find other emails that share the same ThreadId but are currently Unassigned
                    if (!string.IsNullOrEmpty(threadId))
                    {
                        var peerEmails = Emails
                            .Where(e => e.ThreadId == threadId && 
                                       e.MessageId != email.MessageId && 
                                       e.Status == EmailStatus.Unassigned)
                            .ToList();

                        foreach (var peer in peerEmails)
                        {
                            // Set thread context so "Link to Thread" button appears
                            peer.ThreadAssignedProjectId = project.Id;
                            peer.ThreadAssignedProjectName = projectName;
                            // Update context state to show as Filed (gray background)
                            peer.ContextState = EmailContextState.Filed;
                        }

                        if (peerEmails.Count > 0)
                        {
                            AppLogger.LogDebug($"[FileEmail] Updated {peerEmails.Count} peer emails in thread {threadId}");
                        }
                    }

                    // Refresh the view to re-apply grouping
                    RefreshEmailsViewGrouping();

                    // Enable tag selector on all attachments (ComboBox becomes visible)
                    foreach (var att in email.AllDisplayableAttachments)
                    {
                        att.IsEmailFiledToProject = true;
                        att.MessageProjectId = project.Id;
                        AppLogger.Info($"[TagDiag] FileEmail — set IsEmailFiledToProject=true on '{att.FileName}', " +
                            $"InboxAttachmentId={att.InboxAttachmentId}, ShowTagSelector={att.ShowTagSelector}");
                    }
                });

