if (e.Data.GetDataPresent(DataFormats.FileDrop))
            {
                string[] droppedFiles = (string[])e.Data.GetData(DataFormats.FileDrop);

                if (!AllowMultipleFiles && droppedFiles.Length != 1)
                {
                    MessageBox.Show("לא ניתן לגרור יותר מקובץ אחד. אנא בחר קובץ אחד בלבד.", "Drag & Drop", MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }

                object targetNode = GetTargetNode(e.GetPosition(AssociatedObject));
                if (targetNode == null)
                {
                    MessageBox.Show("לא ניתן לזהות על איזה אלמנט בוצע הדרופ.", "Drag & Drop", MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }

                bool isInternalDrag = e.Data.GetDataPresent("MyAppInternalDrag");

                Action processFiles = async () =>
                {
                    foreach (var filePath in droppedFiles)
                    {
                        bool isReady = await WaitUntilFileReadyAsync(filePath);
                        if (isReady)
                        {
                            var dropInfo = new FileDropInfo
                            {
                                FilePath = filePath,
                                TargetNode = targetNode
                            };

                            if (FileDroppedCommand?.CanExecute(dropInfo) == true)
                                FileDroppedCommand.Execute(dropInfo);
                        }
                        else
                        {
                            MessageBox.Show($"לא הצלחתי לקבל גישה לקובץ: {filePath}");
                        }

                        if (!AllowMultipleFiles)
                            break;
                    }
                };

                if (isInternalDrag)
                {
                    Application.Current.Dispatcher.BeginInvoke(processFiles, System.Windows.Threading.DispatcherPriority.Background);
                }
                else
                {
                    processFiles();
                }
            }

