        {
            // Detect renames of tracked files and warn the user
            if (e is RenamedEventArgs renamed)
            {
                CheckRenamedFileInstance(renamed);
            }

            // Debounced in-place rescan: re-runs file integration against the
            // EXISTING folder tree so TreeView IsExpanded state is preserved.
            // (Previously this called LoadUnifiedTree() which clears RootFolders
            // and rebuilds every node from scratch, collapsing the tree.)
            ScheduleInPlaceRescan();
        });

