snippetModel.unrestricted:
Application.Current.Dispatcher.Invoke(() =>
        {
            // Merge into existing FolderFiles instead of clearing — preserves
            // TreeView IsExpanded state and keeps bindings firing on the same
            // node instances.
            var desired = new List<ProjectFileNode>(treeMap.Values);
            if (extRoot.Alternatives.Any() && !folderNode.FolderFiles.Contains(extRoot))
                desired.Add(extRoot);
            else if (extRoot.Alternatives.Any())
                desired.Add(extRoot);

            // Remove nodes no longer present.
            for (int i = folderNode.FolderFiles.Count - 1; i >= 0; i--)
            {
                var existing = folderNode.FolderFiles[i];
                if (existing.IsExternal)
                {
                    if (!extRoot.Alternatives.Any() || !ReferenceEquals(existing, extRoot))
                    {
                        if (!extRoot.Alternatives.Any())
                            folderNode.FolderFiles.RemoveAt(i);
                    }
                    continue;
                }
                if (!desired.Contains(existing))
                    folderNode.FolderFiles.RemoveAt(i);
            }

            // Add nodes that aren't there yet (preserve order: project files first,
            // then unfiled bucket).
            foreach (var n in treeMap.Values)
            {
                if (!folderNode.FolderFiles.Contains(n))
                    folderNode.FolderFiles.Add(n);
            }
            if (extRoot.Alternatives.Any() && !folderNode.FolderFiles.Contains(extRoot))
                folderNode.FolderFiles.Add(extRoot);
        });

