get
        {
            var hex = _color ?? NodeType switch
            {
                "Start" => "#4CAF50",
                "End" => "#F44336",
                "Decision" => "#FF9800",
                "Fork" => "#9C27B0",
                "Join" => "#009688",
                "SubWorkflow" => "#795548",
                _ => "#2196F3"
            };
            try
            {
                return new SolidColorBrush(
                    (Color)ColorConverter.ConvertFromString(hex));
            }
            catch
            {
                return Brushes.SteelBlue;
            }
        }

