get
            {
                var converter = new BrushConverter();
                
                // 🥇 PRIORITY 1: YELLOW (Mismatch Warning)
                // This MUST be first. Safety first - even if project matches context.
                if (ShowMismatchWarning) return (Brush)converter.ConvertFrom("#FFFFD54F")!; // Amber
                
                // 🥈 PRIORITY 2: GREEN (Matches Current Context)
                // Email is filed in Gmail AND matches the currently selected project in UI
                if (IsFiledInGmail && ContextProjectId.HasValue && LabelProjectId == ContextProjectId)
                    return (Brush)converter.ConvertFrom("#C8E6C9")!; // Light Green
                
                // 🥉 PRIORITY 3: Standard States
                // Filed in Gmail but to a DIFFERENT project than selected
                if (IsFiledInGmail) return (Brush)converter.ConvertFrom("#E0E0E0")!; // Gray
                
                // PURPLE: Pending status (must be before thread history and white)
                if (Status == EmailStatus.Pending)
                    return (Brush)converter.ConvertFrom("#F3E5F5")!; // Light Lilac/Purple
                
                // Has thread history (linkable) = Light Gray
                if (HasThreadHistory) return (Brush)converter.ConvertFrom("#F5F5F5")!;
                
                // Personal/Irrelevant = Blue
                if (Status == EmailStatus.Personal || Status == EmailStatus.Irrelevant) 
                    return (Brush)converter.ConvertFrom("#E3F2FD")!;
                
                // New email = White
                return Brushes.White;
            }

